/* gi hun global ? */
body::after {
  content: "";
  position: fixed;
  bottom: 20px;
  right: 20px;
  width: 120px;
  height: 120px;

  background-image: url("https://upload.wikimedia.org/wikipedia/en/3/3c/Clippy-Microsoft-Office-Assistant.png");
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;

  z-index: 999999;
  pointer-events: none;
  opacity: 0.9;
}
